SELECT CASE WHEN ss.revenue >= 4200 THEN 'high' WHEN ss.revenue >= 1200 THEN 'mid' ELSE 'low' END AS revenue_bucket, SUM(i.quantity) AS total_quantity, COUNT(i.quantity) AS quantity_count FROM inventory i LEFT JOIN store_sales ss ON i.store_id = ss.store_id AND i.product_id = ss.product_id WHERE i.quantity > 69 GROUP BY CASE WHEN ss.revenue >= 4200 THEN 'high' WHEN ss.revenue >= 1200 THEN 'mid' ELSE 'low' END;
